(function(root){
'use strict';
const formats=['Abstract','Poster','Specific Aims','IRB Protocol','Manuscript'];
const studies=['Retrospective/Chart Review','Existing Dataset','Prospective/Observational','Interventional/Pilot','Evidence Synthesis'];
const esc=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeMaterial(url){return typeof url==='string'&&(/^assets\/project-examples\/[a-zA-Z0-9_./-]+$/.test(url)&&!url.includes('..')||/^https:\/\//.test(url)&&(()=>{try{return new URL(url).protocol==='https:';}catch{return false;}})());}
function approved(items){
 if(!Array.isArray(items))throw Error('Project examples must be an array.');
 return items.filter(p=>p.approvedForPublicDisplay===true&&p.facultyReviewed===true).map(p=>{
  for(const key of ['id','title','authors','studyType','question','design','feasibility','conclusion','limitations','status'])if(typeof p[key]!=='string'||!p[key].trim())throw Error('Project example is missing '+key);
  if(!/^[a-z0-9-]+$/.test(p.id)||!['Published','Presented','Completed'].includes(p.status))throw Error('Invalid project example identity or status.');
  if(!Array.isArray(p.materials)||!p.materials.length||p.materials.some(m=>!formats.includes(m.format)||typeof m.label!=='string'||!m.label.trim()||!safeMaterial(m.url)))throw Error('Invalid project example materials.');
  return p;
 });
}
function filter(items,options={}){const terms=String(options.query||'').toLowerCase().split(/\s+/).filter(Boolean);return approved(items).filter(p=>(!options.project||p.id===options.project)&&(!options.study||p.studyType===options.study)&&(!options.status||p.status===options.status)&&(!options.format||p.materials.some(m=>m.format===options.format))&&terms.every(w=>[p.title,p.authors,p.studyType,p.question,p.design,p.feasibility,p.conclusion,p.limitations,...(p.tags||[]),...p.materials.map(m=>m.format)].join(' ').toLowerCase().includes(w)));}
function searchRecords(items){const library={id:'project-examples-library',name:'Project Examples and Development Tools',summary:'Abstracts, posters, specific aims pages, and IRB protocol planning for feasible PCCM projects.',url:'#examples',type:'example',category:'Project examples',topic:'Project development',access:'Public learning resources and printable development worksheets.',tags:['abstract','poster','specific aims','IRB protocol','retrospective','prospective','secondary analysis','pilot','project development']};return [library,...approved(items).map(p=>({id:'example-'+p.id,name:p.title,summary:p.question+' '+p.design+' '+p.conclusion,url:'#examples?project='+encodeURIComponent(p.id),type:'example',category:'Project examples',topic:p.studyType,access:'Public, faculty-reviewed teaching example.',tags:[p.authors,p.studyType,p.feasibility,p.status,...p.materials.map(m=>m.format),...(p.tags||[])]}))];}
function cards(items){return items.map(p=>`<article class="resource-card project-example" id="example-${esc(p.id)}"><p class="card-tag">${esc(p.studyType)} · ${esc(p.status)}${p.year?' · '+esc(p.year):''}</p><h3>${esc(p.title)}</h3><p class="example-credit">${esc(p.authors)}</p><dl>${[['Research Question',p.question],['Study Structure',p.design],['Why It Was Feasible',p.feasibility],['Valid Conclusion',p.conclusion],['What It Cannot Establish',p.limitations]].map(([label,value])=>`<dt>${label}</dt><dd>${esc(value)}</dd>`).join('')}</dl>${p.citation?`<p class="quiet-note">${esc(p.citation)}</p>`:''}<ul class="example-materials">${p.materials.map(m=>`<li><a href="${esc(m.url)}" ${m.url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${esc(m.label)} <span class="quiet-note">(${esc(m.format)})</span></a></li>`).join('')}</ul></article>`).join('');}
function page(items){const count=approved(items).length;return `<section class="page-head"><div class="container"><h1>Project Examples</h1><p>Learn how a focused question becomes a feasible study and a defensible conclusion.</p></div></section><div class="container section examples-page"><p class="examples-principle"><strong>A successful project answers its question with a valid conclusion.</strong> A useful result can be positive, negative, or inconclusive. The design, precision, limitations, and interpretation matter.</p><nav class="example-jumps" aria-label="Project Library Sections"><a href="#examples" data-example-section="completed-projects">Completed Projects</a><a href="#examples" data-example-section="development-tools">Specific Aims and Study Planning</a><a href="#examples" data-example-section="protocol-guidance">IRB Protocols</a></nav><section id="completed-projects"><h2>Completed Projects: Abstracts and Posters</h2><p>Each faculty-reviewed entry connects the research question, design, practical scope, conclusion, and limitations. Where available, compare the initial aims and protocol with the final abstract, poster, or publication.</p>${count?`<div class="examples-controls"><label>Search Projects<input id="examples-query" type="search" placeholder="Topic, method, author, or material type"></label><label>Study Type<select id="examples-study"><option value="">All Study Types</option>${[...new Set(approved(items).map(p=>p.studyType))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>Material<select id="examples-format"><option value="">All Materials</option>${formats.map(f=>`<option>${f}</option>`).join('')}</select></label><label>Project Status<select id="examples-status"><option value="">All Statuses</option>${['Published','Presented','Completed'].map(s=>`<option>${s}</option>`).join('')}</select></label></div><p id="examples-count" role="status"></p><div class="directory-grid" id="example-results"></div>`:'<div class="examples-empty"><h3>Help Build the Faculty Collection</h3><p>No completed-project examples have been added yet. Share an abstract or poster that demonstrates a feasible PCCM study; include the original specific aims and a shareable protocol when available. Use the development tools below to start shaping a project now.</p></div>'}</section><section id="development-tools"><h2>Specific Aims and Study Planning</h2><p>Printable, editable planning worksheets for discussion with your mentor. These are teaching tools, not completed faculty projects.</p><div class="directory-grid">${[
 ['specific-aims','Specific Aims Page','Define the gap, objective, hypothesis or question, aims, approach, and expected contribution in one page.'],
 ['abstract-poster','Abstract and Poster Structure','Connect the objective, design, denominators, results, limitations, and conclusion without overstating the findings.']
].map(([id,name,summary])=>worksheetCard(id,name,summary)).join('')}</div></section><section id="protocol-guidance"><h2>IRB Protocols by Study Type</h2><p>Use these planning outlines to organize a mentor discussion, then use the current <a href="https://www.lsuhsc.edu/administration/academic/ors/irb/irb_protocol_templates.aspx" target="_blank" rel="noopener noreferrer">LSU Health IRB Protocol Templates ↗</a> for submission. Historical protocols are examples of structure, not permission to copy an approval or assume the same review category.</p><div class="directory-grid">${[
 ['retrospective','Retrospective/Chart Review','Define the cohort, index date, source records, variables, missingness, confounding, and data protection.'],
 ['secondary-data','Existing Dataset or Specimen Analysis','Align a focused question with the available variables, consent restrictions, access agreements, and analytic sample.'],
 ['prospective','Prospective Observational Study','Specify recruitment, measurements, follow-up, participant burden, data collection, and the analysis plan.'],
 ['interventional','Interventional or Pilot Study','Define allocation, intervention delivery, feasibility outcomes, safety oversight, stopping criteria, and a proportionate analysis plan.']
].map(([id,name,summary])=>worksheetCard(id,name,summary)).join('')}</div><p class="quiet-note">For creation of a database or biobank, use the dedicated template on the <a href="https://www.lsuhsc.edu/administration/academic/ors/irb/irb_protocol_templates.aspx" target="_blank" rel="noopener noreferrer">LSU Health protocol page</a>. Current <a href="https://www.lsuhsc.edu/administration/academic/ors/irb/consent_form_templates.aspx" target="_blank" rel="noopener noreferrer">LSU Health consent templates</a> and <a href="https://lsuhsc.kuali.co/" target="_blank" rel="noopener noreferrer">Kuali Research</a> are available separately.</p></section><details class="project-guide"><summary>Share an Example for This Library</summary><p>Send the hub maintainer the shareable abstract or poster, author credit, study type, and a few sentences about feasibility and what the conclusion can support. Include an aims page or protocol if the authors can share it publicly. A faculty review and author permission are needed before posting. Remove participant information and confidential material.</p><p>An abstract or poster can be included without a published paper. Its status will be labeled accurately; methodological value does not depend on a statistically significant result.</p></details></div>`;}
function worksheetCard(id,name,summary){return `<article class="resource-card"><p class="card-tag">Development Worksheet</p><h3>${name}</h3><p>${summary}</p><p class="worksheet-link"><a href="assets/project-tools/${id}.html" target="_blank" rel="noopener noreferrer">Open Printable Worksheet ↗</a></p></article>`;}
function mount(items,params=new URLSearchParams()){
 document.querySelectorAll('[data-example-section]').forEach(a=>a.addEventListener('click',event=>{event.preventDefault();const target=document.getElementById(a.dataset.exampleSection);target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView({behavior:'smooth',block:'start'});}));
 if(!approved(items).length)return;
 const ids=['examples-query','examples-study','examples-format','examples-status'];
 const nodes=ids.map(id=>document.getElementById(id));
 const refresh=()=>{const matches=filter(items,{query:nodes[0].value,study:nodes[1].value,format:nodes[2].value,status:nodes[3].value,project:params.get('project')||''});document.getElementById('examples-count').textContent=matches.length+' project'+(matches.length===1?'':'s');document.getElementById('example-results').innerHTML=matches.length?cards(matches):'<p>No matching projects. Clear a filter or try another term.</p>';};
 nodes[0].value=params.get('q')||'';
 nodes.forEach((n,i)=>n.addEventListener(i===0?'input':'change',refresh));refresh();
}
const api={approved,filter,searchRecords,page,mount,safeMaterial};if(typeof module!=='undefined'&&module.exports)module.exports=api;root.ProjectExamples=api;
})(typeof window!=='undefined'?window:globalThis);
